[Resource from github at repo://missingbulb/hitbut/sha/03f34fcccff1e3ce611aeb5a2732aea164d71c63/contents/src/backend/detection/run.ts] // One persona, one subject: read the stance series and record what it says.
//
// Everything defensible about a finding comes from here being boring — the maths is in
// `series.ts` and takes no store, this takes no model, and what a reader ends up seeing is
// which utterances a finding rests on plus the model and prompt that placed them.
import type { Corpus } from '../corpus/store.ts';
import type { Finding } from '../../shared/types.ts';
import { anomaliesIn, trendChangeIn, DEFAULTS, type Point, type Thresholds } from './series.ts';

export type DetectOptions = {
  corpus: Corpus;
  /** Which placements to read: a series must never mix two models or two prompts. */
  versions: { modelVersion: string; promptVersion: string };
  surfacingThreshold: number;
  thresholds?: Thresholds;
};

/**
 * Confidence in a finding, from how far the thing that triggered it exceeded its bar.
 *
 * A deliberately blunt mapping rather than a calibrated probability: it exists so the
 * surfacing threshold has something to compare against, and calling it a probability would
 * be dressing a rule of thumb up as a measurement.
 */
const scoreFor = (observed: number, bar: number): number => Math.min(1, observed / (bar * 2));

export async function detect(options: DetectOptions, figureId: string, clusterId: string): Promise<Finding[]> {
  const thresholds = options.thresholds ?? DEFAULTS;
  const series = await options.corpus.stanceSeries(figureId, clusterId, options.versions);
  const points: Point[] = series.map(({ utterance, stance }) => ({
    utteranceId: utterance.id,
    position: stance.position,
    saidAt: utterance.saidAt?.value ?? null,
  }));

  const recorded: Finding[] = [];
  const utteranceById = new Map(series.map(({ utterance }) => [utterance.id, utterance]));

  for (const anomaly of anomaliesIn(points, thresholds)) {
    const utterance = utteranceById.get(anomaly.utteranceId);
    if (!utterance) continue;
    recorded.push(await options.corpus.recordFinding({
      figureId,
      clusterId,
      kind: 'anomaly',
      rationale: `ההתבטאות הזו רחוקה ב־${anomaly.distance.toFixed(2)} מהעמדה שהדמות מחזיקה בנושא הזה בדרך כלל.`,
      score: scoreFor(anomaly.distance, thresholds.anomalyDistance),
      // The point of the finding: not that a position moved but that it moved *here*.
      venue: utterance.venue,
      audience: utterance.audience,
      restsOn: [{ utteranceId: utterance.id, role: 'deviating' }],
      ...options.versions,
    }, options.surfacingThreshold));
  }

  const change = trendChangeIn(points, thresholds);
  // Without both ends dated there is no interval, and an interval is the whole of what a
  // trend change claims — so there is nothing to record rather than something to record
  // vaguely.
  if (change?.changed) {
    const size = Math.abs(change.toLevel - change.fromLevel);
    recorded.push(await options.corpus.recordFinding({
      figureId,
      clusterId,
      kind: 'trend-change',
      rationale: `העמדה בנושא עברה מ־${change.fromLevel.toFixed(2)} ל־${change.toLevel.toFixed(2)} בין שתי ההתבטאויות האלה.`,
      score: scoreFor(size, thresholds.stepSize),
      changed: change.changed,
      restsOn: [
        { utteranceId: change.before.utteranceId, role: 'before' },
        { utteranceId: change.after.utteranceId, role: 'after' },
      ],
      ...options.versions,
    }, options.surfacingThreshold));
  }

  return recorded;
}

[Resource from github at repo://missingbulb/hitbut/sha/03f34fcccff1e3ce611aeb5a2732aea164d71c63/contents/src/backend/acquisition/registry.ts] // What a source module is, and what it has to say about itself before the pipeline will
// run it. There is no support channel for any of these sites, so the two declarations
// below are the only durable record of the reconnaissance that produced the parser.
import { VENUES } from '../../shared/types.ts';
import type { Audience, Language, SourceKind, Venue } from '../../shared/types.ts';

/**
 * Where the module reads its data, in the order of preference the reconnaissance works
 * down: the hydration blob a server-rendered app embeds, then the endpoint a single-page
 * app fetches its rows from, and only then the markup — which a redesign breaks.
 */
export type DataSurface = 'hydration' | 'api' | 'markup';

const SURFACES: DataSurface[] = ['hydration', 'api', 'markup'];

/** One document worth fetching, keyed the way the source itself keys it. */
export type SourceDocument = {
  /** Stable at the source. With the module id, this is what "already fetched" means. */
  key: string;
  url: string;
};

/** A statement as the extractor read it — the speaker by name, because ids are ours to mint. */
export type RawStatement = {
  ordinal: number;
  speaker: { displayName: string; role: string };
  quote: string;
  language: Language;
  /** null when the document does not establish when it was said. */
  saidAt: string | null;
  context: string | null;
  topics: string[];
  /**
   * Where it was said, when this passage was said somewhere other than the module's usual
   * room — a witness at a committee inside a plenary transcript, a quote from a rally
   * inside an article. Absent means the module's `venue`.
   */
  venue?: Venue;
  /** Who it was addressed to, where the document establishes one. */
  audience?: Audience;
};

export type SourceModule = {
  id: string;
  publisher: string;
  kind: SourceKind;
  surface: DataSurface;
  /**
   * How fast this source actually moves. A transcript archive and a press feed do not
   * share a clock, and running everything on the fastest one re-learns a static document
   * thousands of times — which is the traffic most likely to get us blocked.
   */
  refreshMinutes: number;
  /**
   * The room this source reports from. A property of the speech act rather than of the
   * document, and the same words to a committee and at a rally are two utterances — so it
   * cannot be guessed from `kind`, which says how the document was published rather than
   * where the speaking happened.
   */
  venue: Venue;
  list(): Promise<SourceDocument[]>;
  extract(payload: string, document: SourceDocument): RawStatement[];
};

export class SourceRegistry {
  #modules = new Map<string, SourceModule>();

  /** Refuses a module that has not declared what the pipeline needs to run it safely. */
  register(module: SourceModule): void {
    const problems: string[] = [];
    if (!module.id) problems.push('an id');
    if (!module.publisher) problems.push('a publisher');
    if (!SURFACES.includes(module.surface)) problems.push(`a data surface (one of ${SURFACES.join(', ')})`);
    if (!Number.isFinite(module.refreshMinutes) || module.refreshMinutes <= 0) problems.push('a positive refresh interval in minutes');
    if (!VENUES.includes(module.venue as (typeof VENUES)[number])) problems.push(`the venue it reports from (one of ${VENUES.join(', ')})`);
    if (typeof module.list !== 'function') problems.push('a list() of documents to fetch');
    if (typeof module.extract !== 'function') problems.push('an extract() from payload to statements');
    if (problems.length) {
      throw new Error(`source module ${module.id || '(unnamed)'} is missing ${problems.join(', ')}`);
    }
    if (this.#modules.has(module.id)) throw new Error(`source module ${module.id} is already registered`);
    this.#modules.set(module.id, module);
  }

  get(id: string): SourceModule | undefined {
    return this.#modules.get(id);
  }

  all(): SourceModule[] {
    return [...this.#modules.values()];
  }
}

/**
 * The modules acquisition runs in production. Empty until the owner picks the first
 * sources off a `map-a-data-source` reconnaissance: a hand-invented sample would prove
 * support for a target the world does not serve. Tracked in #28.
 */
export function productionRegistry(): SourceRegistry {
  return new SourceRegistry();
}

